            if (marketingInput) decisions.marketingBudget = parseFloat(marketingInput.value);

            var catalogInput = document.getElementById('catalogBudgetInput');
            if (catalogInput) decisions.catalogBudget = parseFloat(catalogInput.value);

            var liveInput = document.getElementById('liveBudgetInput');
            if (liveInput) decisions.liveBudget = parseFloat(liveInput.value);

            var syncInput = document.getElementById('syncFocusInput');
            if (syncInput) decisions.syncFocus = parseInt(syncInput.value);

            if (!decisions.artistBudget || decisions.artistBudget < 100 || decisions.artistBudget > 2000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('artist_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.marketingBudget || decisions.marketingBudget < 50 || decisions.marketingBudget > 1000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }
            if (!isFinite(decisions.catalogBudget) || decisions.catalogBudget < 0 || decisions.catalogBudget > 3000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('catalog_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.liveBudget || decisions.liveBudget < 100 || decisions.liveBudget > 2000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('live_warning'), 'warning'
                );
                return false;
            }

            var totalSpend = (decisions.artistBudget + decisions.marketingBudget + decisions.catalogBudget + decisions.liveBudget) * 1000;
            var availableCash = window.mySimulation.state.domainState.cash;
            if (totalSpend > availableCash) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var healthFactor = ds.artistHealth / 100;
            var streamingRev = Math.round(600000 * healthFactor * (1 + d.marketingBudget / 800) * round.streamingMult);
            var publishingRev = Math.round(ds.catalogValue * 0.012 * (1 + d.syncFocus * 0.06) * round.publishingMult);
            var liveRev = Math.round(d.liveBudget * 1000 * (0.9 + healthFactor * 0.8) * round.liveMult);
            var syncRev = Math.round(ds.catalogValue * 0.003 * d.syncFocus * round.syncMult);

            var totalRevenue = streamingRev + publishingRev + liveRev + syncRev;
            // v1.2.0: a catalog acquisition is an investment, as the case treats it: paid from cash and booked at cost
            // as catalog value, never charged to Net Profit. Until v1.1.0 it was both added to the catalog and expensed
            // in full, so every random budget with a catalog purchase ended the run at a loss and scored 0.
            var catalogSpend = (d.catalogBudget || 0) * 1000;
            var totalCosts = (d.artistBudget + d.marketingBudget + d.liveBudget) * 1000;
            var operatingCosts = 250000;
            var profit = totalRevenue - totalCosts - operatingCosts;

            var healthChange = (d.artistBudget - 300) / 150 - 3 + round.healthBonus;
            ds.artistHealth = Math.max(0, Math.min(100, Math.round(ds.artistHealth + healthChange)));

            ds.catalogValue += catalogSpend;
            ds.catalogValue = Math.round(ds.catalogValue * round.catalogAppreciation);

            ds.cash += profit - catalogSpend;
            ds.totalRevenue += totalRevenue;
            ds.totalProfit += profit;

            ds.monthlyListeners = Math.round(2000000 * (ds.artistHealth / 65) * (1 + d.marketingBudget / 1000));
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: this._platformScore(ds.totalProfit, ds.artistHealth, ds.catalogValue) });

            ds.revenueHistory.push(totalRevenue);
            ds.profitHistory.push(profit);
            ds.catalogHistory.push(ds.catalogValue);
            ds.streamingHistory.push(streamingRev);
            ds.publishingHistory.push(publishingRev);
            ds.liveHistory.push(liveRev);
            ds.syncHistory.push(syncRev);

            var resultsPanel = document.getElementById('resultsPanel');
            if (resultsPanel) resultsPanel.style.display = 'block';

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({
                    currentPeriod: __eqilNext
                });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                streamingRev: streamingRev,
                publishingRev: publishingRev,
                liveRev: liveRev,
                syncRev: syncRev,
                totalRevenue: totalRevenue,
                totalCosts: totalCosts + operatingCosts,
                profit: profit,
                artistHealth: ds.artistHealth,
                catalogValue: ds.catalogValue,
                cash: ds.cash
            };
        }

