        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) {
                return r.results ? r.results.profit : 0;
            });
            var revenues = history.map(function(r) {
                return r.results ? r.results.totalRevenue : 0;
            });
            var totalProfit = profits.reduce(function(s, p) {
                return s + p;
            }, 0);
            var totalRevenue = revenues.reduce(function(s, r) {
                return s + r;
            }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastRecord = history[history.length - 1];
            // v1.1.0 fix: framework history records expose `.results` (which carries
            // catalogValue and artistHealth), not a `.domainState` snapshot. Reading
            // domainState here always fell back to the 10M/65 defaults, so catalogGrowth
            // was stuck at 0.0% and the Industry Leader / Music Mogul tiers (which gate on
            // finalCatalog and finalHealth) were unreachable. Prefer results; keep the
            // domainState/ default paths as fallbacks for robustness.
            var finalRec = lastRecord.results || {};
            var finalCatalog = (finalRec.catalogValue != null) ? finalRec.catalogValue :
                (lastRecord.domainState ? lastRecord.domainState.catalogValue : 10000000);
            var catalogGrowth = ((finalCatalog - 10000000) / 10000000 * 100).toFixed(1);
            var finalHealth = (finalRec.artistHealth != null) ? finalRec.artistHealth :
                (lastRecord.domainState ? lastRecord.domainState.artistHealth : 65);

            var t = function(k) { return window.mySimulation.t(k); };
            var performance = t('perf_developing');
            if (totalProfit > 500000 && finalHealth >= 60) performance = t('perf_competitive');
            if (totalProfit > 1500000 && finalHealth >= 70 && finalCatalog > 11000000) performance = t('perf_leader');
            if (totalProfit > 2500000 && finalHealth >= 80 && finalCatalog > 12000000) performance = t('perf_mogul');

            var insights = [];
            if (avgProfit > 800000) {
                insights.push(t('ins_profit_high'));
            } else if (avgProfit > 300000) {
                insights.push(t('ins_profit_mid'));
            } else {
                insights.push(t('ins_profit_low'));
            }

            if (finalCatalog > 12000000) {
                insights.push(t('ins_catalog_high'));
            } else if (finalCatalog < 9500000) {
                insights.push(t('ins_catalog_low'));
            }

            if (finalHealth >= 75) {
                insights.push(t('ins_health_high'));
            } else if (finalHealth < 55) {
                insights.push(t('ins_health_low'));
            }

            return {
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                avgProfit: Math.round(avgProfit),
                catalogGrowth: catalogGrowth + '%',
                finalArtistHealth: finalHealth,
                performance: performance,
                insights: insights
            };
        }

